xperience_years'=>'Experience (Years)','current_salary'=>'Current Salary','expected_salary'=>'Expected Salary','preferred_role'=>'Preferred Role'] as $name=>$label)<div><label class="label">{{$label}}</label><input class="field" name="{{$name}}" value="{{old($name,$profile->{$name})}}" {{$name==='first_name'?'required':''}}></div>@endforeach<div class="full"><label class="label">Address</label><textarea class="field" name="address">{{old('address',$profile->address)}}</textarea></div><div class="full"><label class="label">Bio</label><textarea class="field" name="bio">{{old('bio',$profile->bio)}}</textarea></div><div class="full"><label class="label">Education</label><textarea class="field" name="education">{{old('education',$profile->education)}}</textarea></div><div class="full"><label class="label">Profile Image</label><input class="field" type="file" name="avatar" accept="image/*"></div><button class="primary">Save Profile</button></form></main></div><section class="panel applications"><h2>My Job Applications</h2>@forelse($applications as $application)<div class="application"><div><strong>{{$application->job->title}}</strong><div style="color:#667085">{{$application->job->company->name}}</div></div><span>{{$application->applied_at?->format('d M Y')}}</span><span class="pill">{{ucwords(str_replace('_',' ',$application->status))}}</span></div>@empty<p style="color:#667085">You have not applied for a portal job yet.</p>@endforelse {{$applications->links()}}</section></div></section>@endsection
